import Foundation
import SwiftUI

/// App-wide localization.
///
/// Generated by `scripts/gen_l10n.py` - edit that file, not this one. Keeping
/// the key enum and all three tables in a single source means they cannot drift;
/// `scripts/check_l10n.py` and `scripts/check_keys.py` verify the result in CI.
enum L10n {

    /// Language the UI is currently rendered in.
    enum Language: String, CaseIterable, Identifiable {
        case english = "en"
        case simplified = "zh-Hans"
        case traditional = "zh-Hant"

        var id: String { rawValue }

        /// Name shown in the picker, always in the language itself.
        var nativeName: String {
            switch self {
            case .english: return "English"
            case .simplified: return "简体中文"
            case .traditional: return "繁體中文"
            }
        }

        var locale: Locale { Locale(identifier: rawValue) }
    }


    /// Every user-visible string.
    enum Key: String, CaseIterable {
        // Header
        case appTitle
        case appSubtitle
        case refresh
        case language
        // Connection
        case pairingLoaded
        case pairingMissing
        case forget
        case gateway
        case apply
        case probe
        case screenshot
        // Pairing
        case pairTitle
        case pairExplanation
        case pin
        case startPairingHost
        case cancel
        case importPairingFile
        case pairStatusIdle
        case pairFirst
        // HUD basics
        case hudSection
        case hudEnable
        case hudEnableFooter
        case hudOpacity
        case hudScale
        case hudScaleFooter
        case hudAlignment
        case hudElements
        case hudElementsFooter
        case hudAdvanced
        case resetDefaults
        case resetMetrics
        case hudConsoleLogging
        case hudConsoleLoggingFooter
        // HUD advanced
        case hudEncoderTiming
        case hudEncoderTimingFooter
        case hudTimelineFrames
        case hudTimelineDelta
        case hudShowZero
        case hudShowRange
        case hudInsights
        case hudInsightTimeout
        case hudInsightInterval
        case hudRusageInterval
        case hudMetricTimeout
        // HUD launch
        case launchOptions
        case terminateExisting
        case showOnlyGames
        case injectedEnvironment
        // Layouts
        case layoutLite
        case layoutFPS
        case layoutDefault
        case layoutRich
        case layoutFull
        // Metrics
        case metricDevice
        case metricLayerSize
        case metricLayerScale
        case metricMemory
        case metricThermal
        case metricFPS
        case metricFPSGraph
        case metricFrameNumber
        case metricGPUTime
        case metricPresentDelay
        case metricFrameInterval
        case metricFrameIntervalGraph
        case metricFrameIntervalHistogram
        case metricMetalCPU
        case metricShaders
        case metricDisk
        case metricGPUTimeline
        case metricTopCommandBuffers
        case metricTopEncoders
        // Alignment
        case alignTopLeft
        case alignTopCenter
        case alignTopRight
        case alignCenterLeft
        case alignCenter
        case alignCenterRight
        case alignBottomLeft
        case alignBottomCenter
        case alignBottomRight
        // Apps
        case installedApps
        case searchPlaceholder
        case noAppsHint
        case noMatchPrefix
        case launch
        case tunnelLog
        case copy
        case clear
        case ok
    }

    // MARK: - Resolution

    /// Translate `key` for `language`, falling back to English and then to the
    /// key itself so a missing entry never traps at runtime.
    static func string(_ key: Key, _ language: Language) -> String {
        let table: [Key: String]
        switch language {
        case .english: table = english
        case .simplified: table = simplified
        case .traditional: table = traditional
        }
        if let value = table[key] { return value }
        if let fallback = english[key] { return fallback }
        return key.rawValue
    }


